/* Original worked chapters for the advanced volume. */
(() => {
  'use strict';
  let language = 'ja';
  const t = (ja, en) => language === 'ja' ? ja : en;
  const p = (ja, en) => `<p>${t(ja, en)}</p>`;
  const f = (a, b) => `<span class="frac"><span>${a}</span><span>${b}</span></span>`;
  const eq = (html, ja = '', en = '') => `<div class="equation"><div class="math">${html}</div>${ja ? `<div class="caption">${t(ja, en)}</div>` : ''}</div>`;
  const s = (n, ja, en, ...body) => `<section><h2><span class="step-no">${String(n).padStart(2, '0')}</span>${t(ja, en)}</h2>${body.join('')}</section>`;
  const note = (ja, en) => `<aside class="callout">${t(ja, en)}</aside>`;
  const sources = {
    szReview: ['Carlstrom, Holder & Reese (2002) · Cosmology with the SZ effect', 'https://arxiv.org/abs/astro-ph/0208192'],
    szSpectrum: ['Birkinshaw · The Kompaneets approximation', 'https://ned.ipac.caltech.edu/level5/Birkinshaw/Birk3_4.html'],
    szPressure: ['Planck (2011) · SZ scaling relations', 'https://doi.org/10.1051/0004-6361/201116458'],
    szIllustration: ['UCLA · Sunyaev–Zeldovich spectrum', 'https://www.astro.ucla.edu/~wright/SZ-spectrum.html'],
    interfaces: ['Maryland · Hydrodynamics: interface instabilities', 'https://pages.astro.umd.edu/~diemer/erebos/teaching/astr670/notes_hydro.pdf'],
    mitInterface: ['MIT · Interfacial phenomena', 'https://ocw.mit.edu/courses/18-357-interfacial-phenomena-fall-2010/04759cfc15c79928ca9f72a18b3864dd_MIT18_357F10_lec_all.pdf'],
    acceleration: ['Maryland · Particle acceleration', 'https://www.astro.umd.edu/~miller/teaching/astr688m/lecture04.pdf'],
    kirk: ['Kirk · Particle acceleration by shocks', 'https://online.kitp.ucsb.edu/online/uhe05/kirk/pdf/Kirk_KITP.pdf'],
    synchrotron: ['NRAO · Essential Radio Astronomy: Synchrotron radiation', 'https://www.cv.nrao.edu/~sransom/web/Ch5.html'],
    radiation: ['Longair · Synchrotron radiation (SI units)', 'https://www.astro.umd.edu/~richard/ASTR480/Beckmann_Longair_Radiation2.pdf'],
    polytrope: ['Princeton · Polytropes', 'https://www.astro.princeton.edu/~gk/A403/polytrop.pdf'],
    wd: ['Princeton · White dwarfs', 'https://www.astro.princeton.edu/~gk/A403/wd.pdf'],
    blast: ['Ohio State · Spherical blastwaves and supernova remnants', 'https://www.astronomy.ohio-state.edu/ryden.1/ast825/ch5-6.pdf'],
    flash: ['FLASH · Sedov explosion test', 'https://sipapu.astro.illinois.edu/~ricker/old-site/research/codes/flash/test_gallery/sedov.html'],
    dimensions: ['MIT OpenCourseWare · Dimensional analysis and similarity', 'https://ocw.mit.edu/courses/res-12-001-topics-in-fluid-dynamics-fall-2024/mitres_12_001_f24_essay2.pdf']
  };
  const chapters = [
    {
      id: 'lane-emden', title: ['Lane–Emden方程式とポリトロープ', 'Lane–Emden equation and polytropes'],
      desc: ['星の内部を解き、チャンドラセカール質量の係数に届く。', 'Solve a stellar interior and recover the coefficient of the Chandrasekhar mass.'],
      minutes: 35, prereq: ['微分・積分、合成関数の微分、常微分方程式の初歩', 'Calculus, the chain rule, and introductory ordinary differential equations'],
      goal: ['静水圧平衡を無次元化し、中心条件から表面まで数値積分して、n＝3で質量が中心密度に依存しない理由を説明する。', 'Nondimensionalize hydrostatic balance, integrate from centre to surface, and explain why mass is independent of central density for n = 3.'],
      question: ['Kと組成を固定する。n＝3で中心密度を8倍にすると、長さ尺度a、半径R、質量Mは何倍になるか。n＝3/2ならどうか。', 'At fixed K and composition, increase the central density eightfold. How do a, R, and M change for n = 3? What about n = 3/2?'],
      answer: ['aとRはρ_c^((1−n)/(2n))、Mはρ_c^((3−n)/(2n))に比例する。n＝3ではaとRが1/2倍、Mは1倍。n＝3/2ではaとRが1/√2倍、Mが√8倍。各系列でnとKが同じなので、無次元の表面ξ₁と質量μₙは変わらない。', 'a and R scale as ρ_c^((1−n)/(2n)); M scales as ρ_c^((3−n)/(2n)). For n = 3, a and R halve while M stays fixed. For n = 3/2, a and R decrease by 1/√2 and M increases by √8. The dimensionless surface ξ₁ and mass μₙ stay fixed because each sequence keeps n and K fixed.'],
      refs: ['polytrope', 'wd'], bridge: 'chandra'
    },
    {
      id: 'rayleigh-taylor', title: ['Rayleigh–Taylor不安定性', 'Rayleigh–Taylor instability'],
      desc: ['重い流体が上にあると、境界の小さな揺れはどう成長するか。', 'How does a small interface disturbance grow when denser fluid is above lighter fluid?'],
      minutes: 30, prereq: ['偏微分、複素指数関数、線形化、流体の運動方程式', 'Partial derivatives, complex exponentials, linearization, and fluid momentum'],
      goal: ['流体境界の運動と圧力の条件から分散関係を導き、Atwood数と波長で成長時間を見積もり、線形理論の範囲を説明する。', 'Derive the interface dispersion relation from kinematic and pressure conditions, estimate growth from Atwood number and wavelength, and identify the linear regime.'],
      question: ['上側の密度が下側の3倍、下向き加速度g＝1 m/s²、波長λ＝2π mとする。成長率と振幅がe倍になる時間は？ 上下の密度を交換したら？', 'Let the top fluid have three times the bottom density, downward g = 1 m/s², and wavelength λ = 2π m. What are the growth rate and e-folding time? What if the fluids are exchanged?'],
      answer: ['A＝(3−1)/(3+1)＝1/2、k＝2π/λ＝1 m⁻¹。σ＝√(Agk)＝1/√2 s⁻¹、τ＝√2 s。上下を交換するとA＝−1/2、ω²＝gk/2>0となり、この理想模型では増幅せず振動する。', 'A = (3−1)/(3+1) = 1/2 and k = 1 m⁻¹. Thus σ = 1/√2 s⁻¹ and the e-folding time is √2 s. Swapping the fluids makes A = −1/2, giving positive ω² = gk/2: oscillation instead of exponential growth in this idealization.'],
      refs: ['interfaces', 'mitInterface'], bridge: 'matter'
    },
    {
      id: 'kelvin-helmholtz', title: ['Kelvin–Helmholtz不安定性', 'Kelvin–Helmholtz instability'],
      desc: ['速度差のエネルギーが、境界の波と渦を育てる。', 'Velocity shear feeds interface waves and, later, vortices.'],
      minutes: 25, prereq: ['RT章の境界条件、複素数、分散関係', 'Interface conditions from the RT chapter, complex numbers, dispersion relations'],
      goal: ['二つの流れの移流を含めて境界条件を書き、KH成長率と波の移動速度を導き、重力による安定化と速度差による不安定化を比較する。', 'Include advection in interface conditions, derive KH growth and pattern speed, and compare gravitational stabilization with shear driving.'],
      question: ['等密度、重力なし、速度差ΔU＝2 m/s、波長λ＝2π mなら成長率は？ 波長を半分にするとどうなるか。成長後の渦の大きさまで線形理論で分かるか。', 'For equal densities, no gravity, ΔU = 2 m/s, and λ = 2π m, what is the growth rate? What happens if the wavelength halves? Does linear theory determine the eventual vortices?'],
      answer: ['σ＝k|ΔU|/2＝1 s⁻¹。波長を半分にするとkが2倍でσも2倍。線形理論は微小な波の初期増幅を記述し、巻き上がった渦や混合は非線形である。速度境界の有限の厚みや粘性などを指定しない理想模型には、最も速く育つ有限波長がない。', 'σ = k|ΔU|/2 = 1 s⁻¹. Halving the wavelength doubles k and σ. Linear theory describes initial small-amplitude growth; rolled-up vortices and mixing are nonlinear. An ideal zero-thickness interface without viscosity or another small-scale regulator has no finite fastest-growing wavelength.'],
      refs: ['interfaces', 'mitInterface'], bridge: 'matter'
    },
    {
      id: 'sedov', title: ['Sedov–Taylor爆風解', 'Sedov–Taylor blast waves'],
      desc: ['次元解析の2/5乗から、衝撃波内部の構造とエネルギー積分へ。', 'From the two-fifths scaling to internal profiles and the energy integral.'],
      minutes: 40, prereq: ['微分・積分、偏微分と連鎖律、理想気体', 'Calculus, partial derivatives and the chain rule, ideal gases'],
      goal: ['膨張則を式変形で導き、保存則を相似変数の常微分方程式に変え、衝撃波条件と全エネルギーから形と係数を求める。', 'Derive the expansion law, reduce conservation laws to similarity ODEs, and use shock conditions and total energy to determine profiles and normalization.'],
      question: ['同じ密度・同じ経過時間で、爆発エネルギーを32倍にすると半径と速度は何倍か。別の爆風で半径Rと衝撃波速度Dが測れたとき、モデルの年齢tはどう求めるか。', 'At the same ambient density and elapsed time, how do radius and speed change if the energy increases by 32? Given a measured shock radius R and shock speed D, what is the model age?'],
      answer: ['RもDもE^(1/5)に比例するので2倍。D＝2R/(5t)よりt＝2R/(5D)。R/Dをそのまま年齢にすると、減速を無視して5/2倍大きく見積もる。この推定はエネルギー保存・一様媒質・強い球対称衝撃波の段階に限る。', 'Both R and D scale as E^(1/5), so both double. Since D = 2R/(5t), the model age is t = 2R/(5D). Using R/D ignores deceleration and overestimates the age by a factor of 5/2. This applies only to an energy-conserving, spherical strong shock in a uniform medium.'],
      refs: ['blast', 'flash', 'dimensions'], bridge: 'structure'
    },
    {
      id: 'shock-acceleration', title: ['衝撃波と粒子加速', 'Shocks and particle acceleration'],
      desc: ['往復による増幅と逃走から、非熱的なべき乗分布を導く。', 'Derive a nonthermal power law from repeated gains and escape.'],
      minutes: 25, prereq: ['対数、等比数列、確率、Rankine–Hugoniot条件', 'Logarithms, geometric sequences, probability, and shock jump conditions'],
      goal: ['拡散衝撃波加速の仮定を述べ、圧縮比から相対論的粒子のエネルギー分布の指数を求め、加速時間と最大エネルギーを区別する。', 'State the assumptions of diffusive shock acceleration, obtain the relativistic-particle energy slope from compression, and distinguish acceleration time from maximum energy.'],
      question: ['圧縮比χ＝3なら、微分エネルギー分布dN/dEの指数sはいくつか。また、粒子を閉じ込められることだけで最大到達エネルギーが確定するか。', 'For compression χ = 3, what is the index s in dN/dE ∝ E^(−s)? Does confinement alone determine the maximum energy?'],
      answer: ['s＝(χ+2)/(χ−1)＝5/2。閉じ込め条件は必要条件であり、加速が天体の寿命内に間に合うか、冷却や逃走より速いかも必要。E⁻²は強い非相対論的衝撃波・試験粒子近似・相対論的粒子などの条件つきの結果である。', 's = (χ+2)/(χ−1) = 5/2. Confinement is necessary, but acceleration must also fit within the source age and beat cooling or escape. E^(−2) is conditional on a strong nonrelativistic shock, a test-particle treatment, relativistic particles, and the stated scattering assumptions.'],
      refs: ['acceleration', 'kirk'], bridge: 'matter'
    },
    {
      id: 'synchrotron', title: ['シンクロトロン放射と電子の冷却', 'Synchrotron radiation and electron cooling'],
      desc: ['加速された電子のエネルギーを、電波・X線のスペクトルへ翻訳する。', 'Translate accelerated electron energies into radio and X-ray spectra.'],
      minutes: 30, prereq: ['ローレンツ因子、比例則、微積分、トムソン断面積', 'Lorentz factor, scaling, calculus, and the Thomson cross section'],
      goal: ['磁場・電子エネルギー・放射周波数の関係を読み、べき乗電子分布から光のスペクトルを求め、放射冷却で高エネルギー側が変わる理由を説明する。', 'Relate magnetic field and electron energy to frequency, derive the spectrum from a power-law electron population, and explain how cooling alters the high-energy emission.'],
      question: ['同じ磁場で電子のγを2倍にすると、代表周波数・放射パワー・冷却時間はどう変わるか。冷却前の電子分布の指数s＝2なら、光学的に薄い放射の指数αはいくつか。', 'At fixed magnetic field, double the electron Lorentz factor. How do characteristic frequency, power, and cooling time change? For an uncooled electron index s = 2, what is the optically thin spectral index α?'],
      answer: ['超相対論的な極限でν_c∝γ²、P∝γ²、t_syn∝γ⁻¹なので、それぞれ4倍・4倍・1/2倍。α＝(s−1)/2＝1/2、すなわちj_ν∝ν⁻¹ᐟ²。自己吸収や冷却が重要な周波数には、そのまま当てはめない。', 'In the ultrarelativistic limit, ν_c ∝ γ², P ∝ γ², and t_syn ∝ γ^(−1): frequency and power quadruple, while cooling time halves. α = (s−1)/2 = 1/2, giving j_ν ∝ ν^(−1/2), away from self-absorption, cooling breaks, and cutoffs.'],
      refs: ['synchrotron', 'radiation'], bridge: 'scattering'
    },
    {
      id: 'sunyaev-zeldovich', title: ['逆コンプトン散乱とSZ効果', 'Inverse Compton scattering and the SZ effect'],
      desc: ['銀河団の熱い電子が、宇宙背景放射に残す圧力のしるし。', 'The pressure imprint of hot galaxy-cluster electrons on the cosmic microwave background.'],
      minutes: 35, prereq: ['トムソン散乱、プランク分布、指数関数の微分、視線積分', 'Thomson scattering, the Planck spectrum, exponential derivatives, and line-of-sight integrals'],
      goal: ['散乱の確率と電子温度からCompton yを求め、熱的SZの周波数依存性を読み、銀河団の電子圧力を測る意味と限界を説明する。', 'Compute Compton y from scattering probability and electron temperature, derive the thermal SZ frequency dependence, and explain what the signal measures about cluster electron pressure.'],
      question: ['一様なガスで電子温度を2倍、密度を半分、視線方向の厚みを同じにすると、τとyはどう変わるか。非相対論的な一次近似で熱的SZのスペクトルは区別できるか。運動学的SZは？', 'In a uniform slab, double the electron temperature, halve its density, and keep its depth fixed. How do τ and y change? Can the first-order nonrelativistic thermal SZ spectra distinguish these cases? What about kinetic SZ?'],
      answer: ['τ＝n_eσ_TLは半分、y＝τk_BT_e/(m_ec²)は同じ。ここで使う熱的SZの一次近似では同じスペクトルになるため、温度と密度を別々には決められない。視線速度も同じなら運動学的SZはτに比例して半分になる。高精度では相対論的補正などに温度の情報があり、この縮退は近似に依存する。', 'τ = n_eσ_TL halves, while y = τk_BT_e/(m_ec²) stays fixed. The first-order thermal spectra used here are identical, so temperature and density cannot be separated. At fixed line-of-sight speed, kinetic SZ halves because it is proportional to τ. Relativistic corrections can carry extra temperature information; this degeneracy belongs to the stated approximation.'],
      refs: ['szReview', 'szSpectrum', 'szPressure', 'szIllustration'], bridge: 'scattering'
    }
  ];
  const bodies = {
    'lane-emden': () => [
      s(1, '全体のつり合いから、薄い殻のつり合いへ', 'From global balance to a thin shell',
        p('入門編ではP∼GM²/R⁴で星を丸ごと見積もった。今度は、中心から半径rまでに含まれる質量m(r)と、その場所の圧力P(r)、密度ρ(r)を分ける。球対称・静止・非回転、ニュートン重力を仮定する。', 'A global estimate P ∼ GM²/R⁴ treats a star as a whole. Now distinguish the enclosed mass m(r), local pressure P(r), and density ρ(r). Assume a static, spherical, nonrotating object with Newtonian gravity.'),
        p('厚みΔrの殻の質量は約4πr²ρΔr。圧力による外向きの正味の力は−4πr²ΔP、重力は内向きに(Gm/r²)4πr²ρΔr。つり合わせてΔrを小さくする。', 'A shell of thickness Δr has mass about 4πr²ρΔr. Its net outward pressure force is −4πr²ΔP; the inward gravitational force is (Gm/r²)4πr²ρΔr. Balance them and take the thin-shell limit.'),
        eq(`${f('dP', 'dr')} = −${f('Gmρ', 'r²')}<br>${f('dm', 'dr')} = 4πr²ρ`),
        note('dP/drは「外へ少し進んだときの圧力の変わり方」。負号は、外側ほど圧力が低いことを表す。二つ目の式は、隣の殻を足すと質量がどれだけ増すかという質量保存である。', 'dP/dr is the local change in pressure with radius. Its negative sign means pressure decreases outward. The second equation expresses mass conservation as successive shells are added.')),
      s(2, '質量を消し、密度と圧力を結ぶ', 'Eliminate mass and close the model',
        p('一つ目をr²/ρ倍するとr²P′/ρ＝−Gm。rで微分し、二つ目を代入する。ここでプライムはr微分を表す。', 'Multiply the first equation by r²/ρ to get r²P′/ρ = −Gm. Differentiate with respect to r and use the second equation; here a prime means an r derivative.'),
        eq(`${f('1', 'r²')}${f('d', 'dr')} (${f('r²', 'ρ')}${f('dP', 'dr')}) = −4πGρ`),
        p('これだけではPとρの関係が足りない。全体で一定のKと指数nを使い、ポリトロープ関係を置く。nは粒子数ではなく、圧力が密度にどう応答するかを指定する指数である。', 'We still need a pressure–density relation. Adopt a polytropic relation with K and n constant throughout the object. The index n is not a particle count: it specifies the density dependence of pressure.'),
        eq(`P = Kρ<sup>1+1/n</sup>　(n > 0)`),
        note('この関係は内部構造のモデルである。すべての星で一定K・一定nが成り立つわけではない。等温球P＝c_s²ρは別の無次元化で扱うため、ここで有限のnを選ぶ模型とは区別する。', 'This is a structural model, not a universal law with constant K and n for all stars. An isothermal sphere P = c_s²ρ requires a different scaling; it is distinct from the finite-n models considered here.')),
      s(3, '単位を外す：無次元化を一行ずつ', 'Remove the units, step by step',
        p('中心密度をρ_cとし、密度の形をθ(ξ)で表す。aは長さ、ξとθは単位を持たない。d/dr＝(1/a)d/dξを使う。', 'Let ρ_c be the central density and use θ(ξ) to describe the profile. The scale a is a length; ξ and θ are dimensionless. Use d/dr = (1/a)d/dξ.'),
        eq(`ρ = ρ<sub>c</sub>θ<sup>n</sup>,　r = aξ<br>P = Kρ<sub>c</sub><sup>1+1/n</sup>θ<sup>n+1</sup>`),
        eq(`${f('1', 'ρ')}${f('dP', 'dr')} = ${f('(n+1)Kρ<sub>c</sub><sup>1/n</sup>', 'a')}${f('dθ', 'dξ')}`),
        p('これを前節の式へ代入する。外側の1/r²と微分も変換すると、左辺の係数は(n+1)Kρ_c^(1/n)/a²、右辺の係数は4πGρ_cになる。両者を同じにするaを選べばよい。', 'Substitute into the previous equation. Transforming the outer 1/r² and derivative leaves a factor (n+1)Kρ_c^(1/n)/a² on the left and 4πGρ_c on the right. Choose a so that these factors match.'),
        eq(`a² = ${f('(n+1)K', '4πG')}ρ<sub>c</sub><sup>(1−n)/n</sup>`),
        eq(`${f('1', 'ξ²')}${f('d', 'dξ')}(ξ²${f('dθ', 'dξ')}) = −θ<sup>n</sup><br>θ″ + ${f('2', 'ξ')}θ′ + θ<sup>n</sup> = 0`, 'Lane–Emden方程式。ここからプライムはξ微分。', 'The Lane–Emden equation; primes now denote ξ derivatives.')),
      s(4, '中心の0/0は、級数で避ける', 'Start at a regular centre',
        p('定義からθ(0)＝1。滑らかな球対称の中心には特別な向きがないのでθ′(0)＝0。ところが数値計算をξ＝0から始めると2θ′/ξが0/0になる。', 'By definition θ(0) = 1. A smooth spherical centre has no preferred direction, so θ′(0) = 0. Direct numerical evaluation at ξ = 0 would nevertheless give 0/0 in 2θ′/ξ.'),
        p('θ＝1+Aξ²+Bξ⁴+…を代入する。定数項は6A+1＝0、ξ²の項は20B+nA＝0。したがって中心のすぐ外で使える出発値が得られる。', 'Insert θ = 1 + Aξ² + Bξ⁴ + … . Constant terms give 6A + 1 = 0; ξ² terms give 20B + nA = 0. This supplies starting values just outside the centre.'),
        eq(`θ = 1 − ${f('ξ²', '6')} + ${f('nξ⁴', '120')} + …<br>θ′ = −${f('ξ', '3')} + ${f('nξ³', '30')} + …`),
        p('小さいε>0でこの値を使い、θ′＝q、q′＝−2q/ξ−θⁿという二つの一階方程式として外へ積分する。θが最初に0になるξ₁を表面とする。ここでは0&lt;n&lt;5を扱う。', 'Start at a small ε > 0 and integrate outward using two first-order equations, θ′ = q and q′ = −2q/ξ − θⁿ. The first zero ξ₁ defines the surface. Here we consider 0 &lt; n &lt; 5.')),
      s(5, '解いて、既知の解と比べる', 'Integrate and compare with a known solution',
        p('n＝1ではθ＝sinξ/ξが解になる。ξ²θ′＝ξcosξ−sinξを微分すると−ξsinξ＝−ξ²θとなり、方程式を満たす。中心極限も1、表面もξ₁＝πと確かめられる。これは数値解法の良い物差しだ。', 'For n = 1, θ = sinξ/ξ is a solution. Differentiating ξ²θ′ = ξcosξ − sinξ gives −ξsinξ = −ξ²θ, as required. The central limit is one and the surface is ξ₁ = π. This provides an independent check on the numerical method.'),
        '<div data-lab="lane-emden"></div>',
        `<details class="advanced"><summary>${t('数値解法の式：4次のRunge–Kutta法', 'The numerical recipe: fourth-order Runge–Kutta')}</summary>${p('y′＝F(x,y)を解くとする。yは一つの値でも、θとqを並べたベクトルでもよい。刻み幅hに対して次の四つの傾きを順番に計算する。', 'For y′ = F(x,y), y can be a scalar or a vector such as (θ,q). With step h, calculate these four slopes in order.')}${eq(`k₁ = F(x,y)<br>k₂ = F(x+h/2, y+hk₁/2)<br>k₃ = F(x+h/2, y+hk₂/2)<br>k₄ = F(x+h, y+hk₃)<br>y(x+h) ≈ y(x) + ${f('h','6')}(k₁+2k₂+2k₃+k₄)`)}</details>`,
        note('パネルは4次のRunge–Kutta法を使用する。小さい区間の傾きを4回評価し、重み1:2:2:1で平均して進める方法である。中心はε＝10⁻⁴から開始し、表面の零点は隣り合う点から補間する。刻み幅を半分にして結果が落ち着くか確かめよう。', 'The panel uses fourth-order Runge–Kutta: evaluate four slopes over a short interval and combine them with weights 1:2:2:1. It starts at ε = 10⁻⁴ and interpolates the surface between neighbouring points. Halve the step to check convergence.')),
      s(6, '無次元の形を、半径と質量に戻す', 'Turn the dimensionless shape into radius and mass',
        p('方程式を中心から表面まで積分すると、密度の積分を表面の傾きで書ける。無次元質量をμₙと名づける。', 'Integrating the equation from centre to surface expresses the density integral through the surface slope. Call this dimensionless mass μₙ.'),
        eq(`μ<sub>n</sub> ≡ ∫<sub>0</sub><sup>ξ₁</sup> ξ²θ<sup>n</sup>dξ = −ξ₁²θ′(ξ₁)<br>R = aξ₁,　M = 4πa³ρ<sub>c</sub>μ<sub>n</sub>`),
        eq(`R ∝ K<sup>1/2</sup>ρ<sub>c</sub><sup>(1−n)/(2n)</sup><br>M ∝ K<sup>3/2</sup>ρ<sub>c</sub><sup>(3−n)/(2n)</sup>`, 'nを固定した系列での比例則。Gも一定。', 'Scaling along a sequence at fixed n; G is also constant.'),
        p('n＝3/2ならM∝ρ_c^(1/2)、R∝ρ_c^(−1/6)なので、固定KでR∝M^(−1/3)。n＝3ならMの中心密度の指数が0になる。星の半径が変わっても、同じKの平衡質量は変わらない。', 'For n = 3/2, M ∝ ρ_c^(1/2) and R ∝ ρ_c^(−1/6), giving R ∝ M^(−1/3) at fixed K. For n = 3, the density exponent in M vanishes: changing radius does not change the equilibrium mass at the same K.')),
      s(7, 'チャンドラセカール質量の係数へ', 'Recover the Chandrasekhar coefficient',
        p('冷たく完全に縮退した電子が超相対論的である極限ではP＝K_URρ^(4/3)、つまりn＝3。量子統計からの入力は次のK_URである。μ_eは電子1個あたりの質量を原子質量定数m_uで割った量、ℏ＝h/(2π)。', 'In the cold, completely degenerate, ultrarelativistic electron limit, P = K_URρ^(4/3), so n = 3. Quantum statistics supplies K_UR below. Here μ_e is mass per electron in units of the atomic mass constant m_u, and ℏ = h/(2π).'),
        eq(`K<sub>UR</sub> = ${f('ℏc', '4')}(3π²)<sup>1/3</sup>(μ<sub>e</sub>m<sub>u</sub>)<sup>−4/3</sup>`),
        p('数値解はξ₁≈6.89685、μ₃≈2.01824を与える。a³ρ_cから中心密度を消すと、入門編で借りた係数を構造計算から求められる。', 'Numerical integration gives ξ₁ ≈ 6.89685 and μ₃ ≈ 2.01824. Cancel the central density in a³ρ_c to recover the structural coefficient supplied in the foundation lesson.'),
        eq(`M = 4πμ₃(${f('K<sub>UR</sub>', 'πG')})<sup>3/2</sup><br>M<sub>Ch</sub> ≈ ${f('5.83', 'μ<sub>e</sub>²')} M<sub>☉</sub> ≈ 1.46 M<sub>☉</sub>　(μ<sub>e</sub> = 2)`),
        note('これは理想化した極限質量である。一般相対論、電子捕獲、クーロン相互作用、温度や回転などは含めていない。n＝3の平衡式だけで動的安定性まで証明したことにはならない。n＝5では有限の零点がなく、n＝0の一様密度模型も上のKρ^(1+1/n)へ直接代入しない。', 'This is an idealized limiting mass. General relativity, electron capture, Coulomb effects, finite temperature, and rotation are omitted. The n = 3 equilibrium equation alone does not establish dynamical stability. The n = 5 solution has no finite zero; the uniform-density n = 0 model also needs separate treatment.'))
    ].join(''),
    sedov: () => [
      s(1, '何を捨てると、爆風は単純になるか', 'When does a blast wave become simple?',
        p('エネルギーEが一度に小さな領域へ放出され、密度ρ₀の一様なガス中に球対称の爆風が広がる。周囲は静止し、初期圧力は衝撃波の圧力に比べて無視できる。理想気体で比熱比γは一定とし、重力・磁場の力・放射冷却を省く。', 'Deposit energy E in a small region of a uniform gas of density ρ₀. A spherical blast expands into initially stationary material with negligible upstream pressure compared with the shock pressure. Use an ideal gas with constant heat-capacity ratio γ, neglecting gravity, magnetic forces, and radiative cooling.'),
        note('超新星残骸なら、掃き集めた周囲の質量が放出物質より十分大きくなった後、放射損失が重要になる前が主な適用段階である。爆発の瞬間や、冷却で薄い殻になる後期まで同じ解を伸ばしてはいけない。', 'For a supernova remnant this model mainly applies after the swept-up mass dominates the ejecta and before radiative losses become important. It does not describe the instant of explosion or the later radiative shell stage.')),
      s(2, '2/5乗は、単位を合わせれば出る', 'Obtain the two-fifths exponent from units',
        p('衝撃波半径をR＝C Eᵃρ₀ᵇtᶜと置く。質量・長さ・時間の単位をそれぞれ比べよう。[E]＝ML²T⁻²、[ρ₀]＝ML⁻³なので、指数は三つの一次方程式で決まる。', 'Write the shock radius as R = C Eᵃρ₀ᵇtᶜ. Since [E] = ML²T⁻² and [ρ₀] = ML⁻³, matching mass, length, and time gives three linear equations for the exponents.'),
        eq(`a+b = 0,　2a−3b = 1,　−2a+c = 0<br>a = ${f('1','5')},　b = −${f('1','5')},　c = ${f('2','5')}`),
        eq(`R = β(${f('Et²','ρ₀')})<sup>1/5</sup>,　D ≡ ${f('dR','dt')} = ${f('2R','5t')}`),
        p('ここから係数をβと呼ぶ。E∼ρ₀R³D²というエネルギーの見積もりでも同じ指数になる。ただし単位のないβは、次元解析だけでは決まらない。内部の形を解いて全エネルギーを合わせる必要がある。', 'Call the dimensionless coefficient β. The energy estimate E ∼ ρ₀R³D² gives the same exponents, but dimensional analysis cannot determine β. We must solve the interior and normalize its total energy.')),
      s(3, 'Rankine–Hugoniot条件を保存則から', 'Derive the Rankine–Hugoniot conditions',
        p('衝撃波と一緒に動く座標で、上流を1、下流を2とする。波面へ流れ込む速さをw₁、流れ出す速さをw₂とし、どちらも正の大きさで書く。薄い定常の波面をまたいで、単位面積あたりの質量流束、運動量流束、エネルギー流束が等しい。', 'In the shock frame, label upstream and downstream states 1 and 2. Let positive w₁ and w₂ be their speeds through the front. Across a thin, steady front, mass, momentum, and energy fluxes per unit area must match.'),
        eq(`ρ₁w₁ = ρ₂w₂<br>p₁+ρ₁w₁² = p₂+ρ₂w₂²<br>${f('w₁²','2')} + ${f('γp₁','(γ−1)ρ₁')} = ${f('w₂²','2')} + ${f('γp₂','(γ−1)ρ₂')}`),
        p('最後の式ではエネルギー流束を共通の質量流束で割った。内部エネルギーだけでなく、圧力がする仕事を含む比エンタルピーγp/[(γ−1)ρ]が入る。', 'The last equation is energy flux divided by the common mass flux. Pressure work adds to internal energy to give the specific enthalpy γp/[(γ−1)ρ].'),
        p('圧縮比χ＝ρ₂/ρ₁と置けばw₂＝w₁/χ。運動量の式からp₂＝p₁+ρ₁w₁²(1−1/χ)。これらをエネルギーの式へ代入し、変化のないχ＝1の根を除くと、次の圧縮解を得る。', 'Set χ = ρ₂/ρ₁, so w₂ = w₁/χ. Momentum conservation gives p₂ = p₁ + ρ₁w₁²(1−1/χ). Substitute both into the energy equation and remove the unchanged-flow root χ = 1 to obtain the compressive solution.'),
        eq(`χ = ${f('(γ+1)ℳ₁²','(γ−1)ℳ₁²+2')},　ℳ₁² ≡ ${f('ρ₁w₁²','γp₁')}`),
        p('強い衝撃波ℳ₁≫1ではχ→(γ+1)/(γ−1)。静止した上流に対してw₁＝D、下流の実験室系速度はu₂＝D−w₂となる。単原子気体γ＝5/3ならχ＝4、u₂＝3D/4、p₂＝3ρ₀D²/4。', 'For a strong shock, ℳ₁ ≫ 1, χ tends to (γ+1)/(γ−1). With stationary upstream gas, w₁ = D and the downstream laboratory speed is u₂ = D − w₂. A monatomic gas with γ = 5/3 gives χ = 4, u₂ = 3D/4, and p₂ = 3ρ₀D²/4.'),
        note('強い衝撃波は「等温で4倍」ではなく、運動エネルギーを熱に変える断熱気体の圧縮限界である。薄い波面ではエントロピーが増える。下の滑らかな領域のエントロピー保存式を波面そのものへ適用しない。', 'The factor four is the strong-shock limit for an adiabatic monatomic gas converting bulk kinetic energy to heat. Entropy increases across the front; the smooth-flow entropy equation below must not be applied through the discontinuity.')),
      s(4, '時間と空間を、一つの変数へ', 'Combine time and radius into one variable',
        p('流体の外向き速度をu、圧力をp、密度をρとする。滑らかな衝撃波内部では、球対称の質量保存・運動方程式・断熱変化が成り立つ。∂は、もう一つの変数を固定した微分を表す。', 'Let u be outward fluid velocity, p pressure, and ρ density. In the smooth interior, spherical mass conservation, momentum balance, and adiabatic evolution hold. A partial derivative ∂ varies one coordinate while holding the other fixed.'),
        eq(`${f('∂ρ','∂t')} + ${f('1','r²')}${f('∂','∂r')}(r²ρu) = 0`),
        eq(`${f('∂u','∂t')} + u${f('∂u','∂r')} = −${f('1','ρ')}${f('∂p','∂r')}`),
        eq(`(${f('∂','∂t')}+u${f('∂','∂r')}) (${f('p','ρ<sup>γ</sup>')}) = 0`),
        p('半径をその時刻の衝撃波半径Rで割り、x＝r/Rとする。密度はρ₀、速度はD、圧力はρ₀D²で割る。形G、V、Zがxだけの関数になる解を探す。', 'Set x = r/R and scale density by ρ₀, velocity by D, and pressure by ρ₀D². Seek profiles G, V, and Z depending only on x.'),
        eq(`ρ = ρ₀G(x),　u = DV(x),　p = ρ₀D²Z(x)<br>${f('∂x','∂r')} = ${f('1','R')},　${f('∂x','∂t')} = −${f('D','R')}x`),
        p('例えば∂ρ/∂t＝−ρ₀(D/R)xG′。質量流束の項はρ₀(D/R)(G′V+GV′+2GV/x)。共通係数を消すと、次節の一つ目になる。', 'For example, ∂ρ/∂t = −ρ₀(D/R)xG′, while the mass-flux derivative is ρ₀(D/R)(G′V + GV′ + 2GV/x). Cancelling the common factor gives the first equation below.')),
      s(5, '相似常微分方程式と境界条件', 'Similarity ODEs and shock boundaries',
        p('R∝t^(2/5)からR(dD/dt)/D²＝−3/2。同じ連鎖律を運動と断熱の式にも使うと、偏微分方程式が三つの常微分方程式へ変わる。ここでプライムはx微分。', 'R ∝ t^(2/5) implies R(dD/dt)/D² = −3/2. Apply the same chain rule to momentum and adiabatic evolution to reduce the PDEs to three ODEs. Primes now denote x derivatives.'),
        eq(`(V−x)G′ + G(V′+2V/x) = 0`),
        eq(`(V−x)V′ − ${f('3','2')}V = −${f('Z′','G')}`),
        eq(`(V−x)(${f('Z′','Z')}−γ${f('G′','G')}) = 3`),
        p('衝撃波の位置はx＝1。前節の跳躍条件を無次元にすると、積分の出発値が決まる。', 'The shock is at x = 1. Nondimensionalizing the jump conditions supplies the starting values.'),
        eq(`G(1) = ${f('γ+1','γ−1')},　V(1) = ${f('2','γ+1')},　Z(1) = ${f('2','γ+1')}`),
        p('γ＝5/3では(4,3/4,3/4)から中心へ向かって解く。物理的な解は中心でV→0、G→0、Zは有限となる。密度が低くても圧力が残るので、一様密度の球を膨らませる模型とは大きく違う。', 'For γ = 5/3 integrate inward from (4, 3/4, 3/4). The physical branch approaches V → 0, G → 0, and finite Z at the centre. Low density can coexist with finite pressure, unlike a uniformly filled expanding sphere.')),
      s(6, '全エネルギーを合わせてβを求める', 'Normalize the total energy to determine β',
        p('全エネルギーは運動エネルギーと内部エネルギーの和。単位体積あたりでρu²/2とp/(γ−1)なので、体積要素4πr²drを掛けて積分する。', 'Total energy is kinetic plus internal energy. Their densities are ρu²/2 and p/(γ−1); integrate using the volume element 4πr²dr.'),
        eq(`I ≡ ∫<sub>0</sub><sup>1</sup> [${f('GV²','2')}+${f('Z','γ−1')}]x²dx<br>E = 4πρ₀R³D²I = ${f('16π','25')}ρ₀${f('R⁵','t²')}I`),
        eq(`β = (${f('25','16πI')})<sup>1/5</sup> ≈ 1.15167　(γ = 5/3)`),
        '<div data-lab="sedov"></div>',
        note('パネルはγ＝5/3固定で、x＝1から0.05までRunge–Kutta法で実際に積分する。GとZの対数を変数にして正値を保つ。中心の小領域の熱エネルギーはZ(0.05)を一定として補い、グラフは未計算のx&lt;0.05を描かない。βはこの数値積分からの近似値である。', 'The panel integrates at fixed γ = 5/3 from x = 1 to 0.05 using Runge–Kutta, evolving logarithms of G and Z to preserve positivity. It approximates the small central thermal-energy contribution with constant Z(0.05); profiles below x = 0.05 are not plotted. The displayed β is a numerical estimate.')),
      s(7, '保存則を使って解を疑う', 'Use conservation laws to challenge the solution',
        p('内部の質量は、半径R以内に初めからあった質量4πρ₀R³/3と一致するはずだ。よって3∫Gx²dx＝1を検算に使える。刻みを細かくして質量比とβが落ち着くことを確かめる。', 'The enclosed mass should equal the initially swept volume times density, 4πρ₀R³/3. Thus 3∫Gx²dx = 1 is an independent check. Refine the step and verify convergence of the mass ratio and β.'),
        p('半径と速度だけならt＝2R/(5D)。密度も分かればE＝ρ₀R⁵/(β⁵t²)と爆発エネルギーを推定できる。ただし観測されたガスの速度と波面の速度Dは同じではない。', 'Radius and shock speed imply t = 2R/(5D). With density as well, infer E = ρ₀R⁵/(β⁵t²). Observed gas velocity is not generally the shock-front speed D.'),
        note('宇宙線の圧力が大きい場合、粒子がエネルギーを持ち去る場合、周囲が非一様な場合には、この理想気体の係数や圧縮比は変わりうる。次の粒子加速章では、まず加速粒子の反作用を無視する極限から始める。', 'Cosmic-ray pressure, particle escape, or a nonuniform medium can change these ideal-gas coefficients and compression ratios. The next chapter begins with acceleration in the limit where energetic particles do not modify the flow.'))
    ].join(''),
    'rayleigh-taylor': () => [
      s(1, '上が重いと、入れ替わる方が楽になる', 'Denser fluid above can lower its potential energy',
        p('重力があると、重い流体が下、軽い流体が上の配置は落ち着いている。逆に上が重いと、境界の少し下がった所には重い流体が入り込み、軽い流体は上がる。位置エネルギーを取り出して、初めの揺れが大きくなるのがRayleigh–Taylor不安定性である。', 'Denser fluid below lighter fluid is a stable arrangement under gravity. If the denser fluid is above, a small downward deformation lets dense fluid sink while lighter fluid rises. Releasing potential energy amplifies the deformation: Rayleigh–Taylor instability.'),
        p('zを上向き、加速度を−g（g>0）とし、平らな境界z＝0の上側を密度ρ₁、下側をρ₂とする。各流体は無限に深く、一様密度・非圧縮・非粘性。表面張力と磁場は省き、今は背景流速を0とする。自己重力の揺らぎを計算するJeans問題とは別で、gは外から与えた加速度である。', 'Take z upward and acceleration −g with g > 0. The upper and lower half-spaces have constant densities ρ₁ and ρ₂. Both are infinitely deep, incompressible, and inviscid, with no surface tension, magnetic field, or background flow. Unlike Jeans instability, we prescribe g rather than calculate perturbed self-gravity.'),
        eq(`ζ(x,t) = Re[ζ₀e<sup>i(kx−ωt)</sup>],　k = ${f('2π','λ')} > 0`),
        note('ζは境界の高さ。複素指数関数は波を計算する道具で、最後に実部Reを取る。ω＝ω_r+iσならe^(−iωt)＝e^(−iω_rt)e^(σt)。したがってσ>0は成長を表す。線形化にはk|ζ|≪1が必要。', 'ζ is interface height. Complex exponentials are a calculational tool; the physical displacement is the real part. For ω = ω_r + iσ, e^(−iωt) = e^(−iω_rt)e^(σt), so σ > 0 means growth. Linearization requires k|ζ| ≪ 1.')),
      s(2, '境界から離れると消える流れを作る', 'Build a flow that decays away from the interface',
        p('境界の外の各領域では、揺らぎの速度をδu＝∇φとするポテンシャル流を考える。非圧縮条件∇·δu＝0から∇²φ＝0。x方向にe^(ikx)で波打つと、z方向はφ″−k²φ＝0となる。無限遠で消える解を選ぶ。', 'In each fluid take potential perturbations δu = ∇φ. Incompressibility, ∇·δu = 0, gives ∇²φ = 0. With x dependence e^(ikx), the vertical equation is φ″ − k²φ = 0. Choose solutions that decay far from the interface.'),
        eq(`φ₁ = a₁e<sup>−kz</sup>e<sup>i(kx−ωt)</sup>　(z > 0)<br>φ₂ = a₂e<sup>kz</sup>e<sup>i(kx−ωt)</sup>　(z &lt; 0)`),
        p('境界は流体と一緒に動くので、境界の鉛直速度∂ζ/∂tと各流体の∂φ/∂zが等しい。一次の精度ではz＝0で評価すればよい。共通の指数関数を省くと、', 'The interface moves with the fluid, so its vertical speed ∂ζ/∂t equals ∂φ/∂z on either side. At first order evaluate at z = 0. Removing the common exponential gives:'),
        eq(`−iωζ₀ = −ka₁ = ka₂<br>a₁ = ${f('iωζ₀','k')},　a₂ = −${f('iωζ₀','k')}`)),
      s(3, '平衡圧力の勾配を忘れない', 'Keep the background pressure gradient',
        p('線形化した運動方程式を空間で積分すると、圧力揺らぎはδp_j＝−ρ_j∂φ_j/∂t＝iρ_jωφ_j。境界では圧力が等しいが、境界そのものがz＝ζへ移っている。背景圧力はdp₀/dz＝−ρgなので、ζだけ移動すると−ρgζも加わる。', 'Spatial integration of linearized momentum gives δp_j = −ρ_j∂φ_j/∂t = iρ_jωφ_j. Pressures match at the displaced interface z = ζ. The equilibrium gradient dp₀/dz = −ρg adds a term −ρgζ when evaluating there.'),
        eq(`δp₁−ρ₁gζ = δp₂−ρ₂gζ<br>δp₁−δp₂ = (ρ₁−ρ₂)gζ`),
        p('前節のa₁、a₂を使うと、δp₁＝−ρ₁ω²ζ₀/k、δp₂＝+ρ₂ω²ζ₀/k。差を取り、ζ₀≠0の波について整理する。', 'The amplitudes above give δp₁ = −ρ₁ω²ζ₀/k and δp₂ = +ρ₂ω²ζ₀/k. Subtract them and cancel nonzero ζ₀.'),
        eq(`−${f('(ρ₁+ρ₂)ω²','k')} = (ρ₁−ρ₂)g<br>ω² = −Agk,　A ≡ ${f('ρ₁−ρ₂','ρ₁+ρ₂')}`),
        p('AはAtwood数。上が重いA>0ならω＝±i√(Agk)なので、成長する枝の成長率はσ＝√(Agk)。上が軽いA<0ならωは実数で、この模型では境界の重力波になる。', 'A is the Atwood number. Denser fluid on top gives A > 0 and ω = ±i√(Agk); the growing branch has σ = √(Agk). If A < 0, ω is real and the interface supports gravity waves in this model.'),
        eq(`τ<sub>grow</sub> = ${f('1','σ')} = √(${f('λ','2πAg')})　(A > 0)`)),
      s(4, '密度比と波長で、時間尺度を確かめる', 'Explore density contrast and wavelength',
        '<div data-lab="rayleigh-taylor"></div>',
        p('密度を両方同じ倍率で増やしてもAは変わらない。波長を4分の1にするとkは4倍、成長率は2倍。二倍になる時間はln2/σであり、1/σはe倍になる時間である。A＝0、速度差なしなら、この理想模型の界面には復元力も成長もない。', 'Multiplying both densities by the same factor leaves A unchanged. Reducing wavelength by four increases k by four and growth rate by two. The doubling time is ln2/σ; 1/σ is the e-folding time. With A = 0 and no shear, this ideal interface has neither restoring force nor growth.')),
      s(5, '線形の波と、非線形の混合を分ける', 'Separate linear growth from nonlinear mixing',
        p('この計算は微小な境界変形の初期段階だけを解く。振幅が波長に近づくと、軽い流体の泡や重い流体の指状構造、巻き込みが生じ、線形理論では追えなくなる。超新星残骸の接触面などでは、流れと一緒に減速する座標で有効加速度と密度の向きを調べる。', 'This calculation describes only the small-amplitude stage. Large bubbles, dense spikes, and entrainment require nonlinear dynamics. At contacts in supernova remnants, examine density ordering relative to the effective acceleration in a frame following the decelerating flow.'),
        note('表面張力・粘性・磁場・界面の有限厚みを省いた模型ではσ∝√kで、短波長ほど速い。したがって最も速く育つ有限の波長は選ばれない。数値計算で格子を細かくしたら構造が変わる場合、物理的な短波長の抑制と初期揺らぎを指定したか確認する。', 'Without surface tension, viscosity, magnetic effects, or finite interface thickness, σ ∝ √k has no finite fastest-growing wavelength. If a numerical result changes with resolution, check the physical small-scale regulator and the prescribed initial perturbations.'))
    ].join(''),
    'kelvin-helmholtz': () => [
      s(1, '重い・軽いが同じでも、速度差は波を育てる', 'Shear can drive waves even at equal density',
        p('二つの流体が境界に沿って違う速さで流れると、境界の波が流れの運動エネルギーを受け取って成長しうる。これがKelvin–Helmholtz不安定性。RTが有効加速度と密度の配置を使うのに対し、KHは速度差を駆動源とする。', 'Two fluids moving at different speeds along an interface can transfer bulk kinetic energy into interface waves. This is Kelvin–Helmholtz instability. RT uses density ordering relative to effective acceleration; KH is driven by shear.'),
        p('RT章と同じ、上側ρ₁・下側ρ₂、非圧縮・非粘性・無限の深さの模型を使う。背景速度U₁、U₂はx方向で各側では一様、境界で不連続とする。まずg＝0、表面張力と磁場なし。波数k>0は流れに平行とする。', 'Use the RT chapter’s incompressible, inviscid, infinitely deep half-spaces, upper density ρ₁ and lower density ρ₂. Background velocities U₁ and U₂ are uniform and parallel to x, discontinuous at the interface. Initially set g = 0, with no surface tension or magnetic field and k > 0 parallel to the flow.'),
        p('<a href="#/advanced/rayleigh-taylor">RT章のポテンシャル流と圧力条件</a>を、移流を含む形へ書き換える。', 'Rewrite the <a href="#/advanced/rayleigh-taylor">RT chapter’s potential flow and pressure conditions</a> to include advection.')),
      s(2, '流れとともに見る周波数を使う', 'Use the frequency seen by each stream',
        p('流体と一緒に移動すると、時間変化は∂/∂t+U_j∂/∂xとなる。e^[i(kx−ωt)]に作用させると−i(ω−kU_j)。各流体に見える周波数をΩ_jと置く。', 'Following each stream changes the time derivative to ∂/∂t + U_j∂/∂x. Acting on e^[i(kx−ωt)] gives −i(ω−kU_j). Define this stream-relative frequency as Ω_j.'),
        eq(`Ω₁ = ω−kU₁,　Ω₂ = ω−kU₂<br>a₁ = ${f('iΩ₁ζ₀','k')},　a₂ = −${f('iΩ₂ζ₀','k')}`),
        p('線形の圧力もδp_j＝−ρ_j(∂/∂t+U_j∂/∂x)φ_jである。境界の圧力を等しくすると、g＝0では次の二次式になる。', 'Pressure perturbations also use δp_j = −ρ_j(∂/∂t + U_j∂/∂x)φ_j. Matching interface pressures gives, for g = 0:'),
        eq(`ρ₁(ω−kU₁)² + ρ₂(ω−kU₂)² = 0`)),
      s(3, '平方完成で、移動と成長を分ける', 'Complete the square to separate drift and growth',
        p('密度で重みを付けた平均速度Ūを引くと、二次式は平方完成できる。ΔU＝U₁−U₂として、', 'Subtract the density-weighted mean velocity Ū and complete the square. With ΔU = U₁ − U₂:'),
        eq(`Ū ≡ ${f('ρ₁U₁+ρ₂U₂','ρ₁+ρ₂')}<br>(ω−kŪ)² = −${f('ρ₁ρ₂','(ρ₁+ρ₂)²')}k²(ΔU)²`),
        eq(`ω = kŪ ± iσ,　σ = ${f('√(ρ₁ρ₂)','ρ₁+ρ₂')}k|ΔU|`),
        p('波はŪで流されながら、一方の枝がe^(σt)で育つ。等密度でもσ＝k|ΔU|/2となり不安定。同じ速度を両側に足すと移動速度だけが変わり、成長率は変わらない。密度が大きく違うほど、同じ速度差に対する成長率は小さくなる。', 'The pattern drifts at Ū while one branch grows as e^(σt). Equal densities still give σ = k|ΔU|/2. Adding the same velocity to both streams changes drift but not growth. Larger density contrast reduces growth at the same shear.'),
        '<div data-lab="kelvin-helmholtz"></div>'),
      s(4, '重力と速度差を、一つの分散関係へ', 'Combine gravity and shear in one relation',
        p('RT章と同じ下向きのgを戻す。圧力条件はρ₁Ω₁²+ρ₂Ω₂²＝(ρ₂−ρ₁)gk。再び平方完成すると、重力の項と速度差の項を同時に読める。', 'Restore the RT chapter’s downward g. Pressure matching becomes ρ₁Ω₁² + ρ₂Ω₂² = (ρ₂−ρ₁)gk. Completing the square again puts gravity and shear in a single relation.'),
        eq(`(ω−kŪ)² = −Agk − ${f('ρ₁ρ₂','(ρ₁+ρ₂)²')}k²(ΔU)²<br>A ≡ ${f('ρ₁−ρ₂','ρ₁+ρ₂')}`),
        p('右辺が正なら移流する振動、負なら成長・減衰の対が現れる。A>0ならRTとKHはともに不安定化する。A<0の安定な密度配置なら重力の項は正で、長い波を支えるが、十分短い波ではk²に比例する速度差の項が勝つ。', 'A positive right-hand side gives advected oscillations; a negative value gives growing and decaying branches. For A > 0, RT and KH both destabilize. For A < 0, gravity supports long waves, but the shear term proportional to k² wins at sufficiently short wavelengths.'),
        note('粘性なし・厚み0の速度境界では、σ∝kで短波長ほど速く、有限の最速波長がない。現実の速度層の厚み、圧縮性、磁場や粘性は結果を変える。ここで「全波長が不安定」と言えるのは、g＝0でこの理想模型を採用した場合である。', 'A zero-thickness inviscid velocity jump has σ ∝ k and no finite fastest-growing wavelength. Finite shear thickness, compressibility, magnetic fields, and viscosity change this. The statement that all wavelengths are unstable applies here to the ideal g = 0 model.')),
      s(5, '線形波を、渦の動画と取り違えない', 'A linear wave is not a vortex simulation',
        p('成長後の波が巻き上がり、渦と混合へ進む過程は非線形である。ジェットと周囲のガス、異なる速さのガス雲などは応用先だが、実際の安定性にはその密度・音速・磁場・速度分布が必要になる。', 'Wave roll-up, vortices, and mixing are nonlinear stages. Jets and surrounding gas or gas clouds moving at different speeds are applications, but their stability depends on actual density, sound speed, magnetic field, and velocity profiles.'),
        p('パネルの波は、導いた分散関係の単一の線形モードを描いたもの。流体方程式を非線形に時間積分した動画ではない。RT・KH・Jeans・Toomreを並べると、何がエネルギーを与え、何が揺らぎを抑えるのか、同じ問いで比較できる。', 'The panel draws a single linear mode of the derived dispersion relation, not a nonlinear fluid simulation. Comparing RT, KH, Jeans, and Toomre instabilities asks the same useful questions: what supplies energy, and what opposes the disturbance?'))
    ].join(''),
    'shock-acceleration': () => [
      s(1, '熱くなるだけではない衝撃波', 'A shock can do more than heat gas',
        p('Rankine–Hugoniot条件はガス全体のつり合いを決めるが、一部の粒子が何度も波面を横切ると、熱分布から遠く離れた高エネルギー成分ができる。ここでは非相対論的な平面の定常衝撃波と、速さv≈cの粒子を考える。', 'Shock jump conditions constrain the bulk gas, but particles that repeatedly cross the front can form a high-energy population far from thermal equilibrium. Consider a steady, planar, nonrelativistic shock and particles with speed v ≈ c.'),
        p('波面の静止系で上流・下流の流速をw₁>w₂>0、圧縮比をχ＝w₁/w₂とする。磁場の乱れによる散乱で、粒子の向きがそれぞれの流体の静止系ではほぼ等方的になると仮定する。加速粒子が流れを変えない「試験粒子近似」を使う。', 'In the shock frame let w₁ > w₂ > 0, with compression χ = w₁/w₂. Scattering by magnetic irregularities approximately isotropizes particles in each local fluid frame. Use the test-particle limit, in which accelerated particles do not modify the flow.'),
        note('静的な磁場のローレンツ力そのものは粒子に仕事をしない。動く散乱体の間を行き来することで、流体の運動エネルギーが粒子へ移る。散乱体がガスに対して大きく動く場合には、以下の単純な指数も修正される。', 'A static magnetic field does no work on a charge. Energy comes from the bulk flow as particles scatter between moving frames. Significant motion of scattering centres relative to the gas modifies the simple spectral result below.')),
      s(2, '一往復の増幅と、戻れなくなる確率', 'Gain and escape in one cycle',
        p('相対速度が小さい二つの流体系を移ると、相対論的粒子のエネルギー変化は一次でΔE/E≈(w₁−w₂)μ/v。波面を横切る粒子は、方向余弦μに比例した重みで数えるので平均μは(∫₀¹μ²dμ)/(∫₀¹μdμ)＝2/3。一往復は二回の横断だから、平均の増幅率gは次になる。', 'For a small relative flow speed, changing between fluid frames changes relativistic particle energy by approximately (w₁−w₂)μ/v to first order. Crossing particles are flux-weighted by the direction cosine μ, giving mean μ = (∫₀¹μ²dμ)/(∫₀¹μdμ) = 2/3. Two crossings make a complete cycle.'),
        eq(`g ≡ ⟨${f('ΔE','E')}⟩<sub>cycle</sub> ≈ ${f('4(w₁−w₂)','3v')}`),
        p('下流の等方的粒子の数密度をn_pとすると、波面を横切る流束はn_pv/4。一方、流れに運ばれて下流遠方へ失われる流束はn_pw₂。両者の比が一往復あたりの逃走確率P_escとなる。', 'For downstream particle number density n_p, the isotropic crossing flux is n_pv/4. The advective loss flux far downstream is n_pw₂. Their ratio gives the escape probability per cycle.'),
        eq(`P<sub>esc</sub> ≈ ${f('4w₂','v')}`),
        p('どちらも流速/粒子速度の一次である。「一次Fermi加速」と呼ぶ理由は、この一次の増幅にある。上流側への逃走はこの理想化では無視している。', 'Both are first order in flow speed divided by particle speed. This is the origin of the name first-order Fermi acceleration. This idealization neglects escape through the upstream boundary.')),
      s(3, '等比数列を消去すると、べき乗になる', 'Eliminate the cycle count to get a power law',
        p('同じE₀から出発したN₀個の粒子を考える。k回の往復を生き残ると、E_k＝E₀(1+g)^k、N_k＝N₀(1−P_esc)^k。対数を取りkを消すだけでよい。', 'Start N₀ particles at E₀. After k surviving cycles, E_k = E₀(1+g)^k and N_k = N₀(1−P_esc)^k. Take logarithms and eliminate k.'),
        eq(`${f('N(>E)','N₀')} = (${f('E','E₀')})<sup>ln(1−P<sub>esc</sub>)/ln(1+g)</sup><br>N(>E) ∝ E<sup>−P<sub>esc</sub>/g</sup>`, '下段はg≪1、P_esc≪1でln(1+g)≈g、ln(1−P_esc)≈−P_escを使う。', 'The second line uses ln(1+g) ≈ g and ln(1−P_esc) ≈ −P_esc for small gains and losses.'),
        p('N(>E)は累積数。エネルギー幅dEあたりの分布は、その負の微分なので指数に1が足される。', 'N(>E) is cumulative. The differential number distribution per energy interval is its negative derivative, adding one to the index.'),
        eq(`${f('dN','dE')} ∝ E<sup>−s</sup>,　s = 1+${f('P<sub>esc</sub>','g')}<br>s = 1+${f('3w₂','w₁−w₂')} = ${f('χ+2','χ−1')}`),
        p('γ＝5/3の強い気体衝撃波ならχ＝4なのでs＝2。これは相対論的粒子の微分エネルギー分布である。運動量空間の分布関数f(p)を使うと、dN＝4πp²f(p)dpのp²が加わるため、同じ解でもf(p)∝p⁻⁴と表す。', 'A strong monatomic gas shock has χ = 4, giving s = 2 for relativistic particles per energy interval. A momentum-space distribution function uses dN = 4πp²f(p)dp, so the same solution is written f(p) ∝ p^(−4).'),
        '<div data-lab="acceleration"></div>'),
      s(4, '指数は出ても、最高エネルギーはまだ出ない', 'A spectral slope does not set the maximum energy',
        p('散乱を空間拡散係数κ₁、κ₂で表す。波面付近に滞在する厚みはおよそκ/w。粒子数を横断流束nv/4で割ると、往復時間はt_cycle≈(4/v)(κ₁/w₁+κ₂/w₂)。これを増幅率gで割れば、エネルギーが対数的に増える時間尺度になる。', 'Describe scattering by spatial diffusion coefficients κ₁ and κ₂. A residence layer has thickness of order κ/w. Dividing its particle content by crossing flux nv/4 gives t_cycle ≈ (4/v)(κ₁/w₁ + κ₂/w₂). Dividing by the gain g gives the local logarithmic acceleration time.'),
        eq(`t<sub>acc</sub>(E) ≡ ${f('E','dE/dt')} ≈ ${f('3','w₁−w₂')}(${f('κ₁','w₁')}+${f('κ₂','w₂')})`),
        p('χ＝4かつκ₁＝κ₂＝κならt_acc＝20κ/w₁²。κがエネルギーに依存する場合、E₀からEまでの総時間は∫t_acc(E′)dE′/E′であり、常にこの一つの値と等しいわけではない。', 'For χ = 4 and κ₁ = κ₂ = κ, t_acc = 20κ/w₁². If κ depends on energy, the time from E₀ to E is ∫t_acc(E′)dE′/E′, not generally a single value of this local timescale.'),
        eq(`r<sub>L</sub> = ${f('p','|q|B')} ≲ L　⇒　E ≈ pc ≲ |q|BLc`, 'SI単位。Lは加速領域の大きさ。', 'SI units; L is the size of the acceleration region.'),
        note('閉じ込め、天体の年齢、下流への移流、上流への逃走、放射冷却を同時に考える。注入される粒子の割合や磁場の乱れの強さは、上の指数の導出からは決まらない。銀河内を伝わって地球へ届く宇宙線の指数も、源でのsと同じとは限らない。', 'Confinement, source age, downstream advection, upstream escape, and radiative cooling all matter. The slope derivation does not determine injection efficiency or magnetic turbulence. Propagation also means the cosmic-ray slope measured at Earth need not equal the source slope.'))
    ].join(''),
    'sunyaev-zeldovich': () => [
      s(1, '銀河団を、背景の光で測る', 'Use background light to measure a galaxy cluster',
        p('宇宙背景放射（CMB）は、ほぼ2.7255 Kの黒体スペクトルを持つ。銀河団の銀河の間には熱い希薄なガスがあり、その自由電子が通過するCMB光子を散乱する。光子が平均として電子からエネルギーを受け取る逆コンプトン散乱により、銀河団の方向のCMBスペクトルが少し変わる。これが熱的Sunyaev–Zel’dovich（スニヤエフ–ゼルドビッチ、SZ）効果である。', 'The cosmic microwave background (CMB) has a nearly blackbody spectrum at 2.7255 K. Hot, diffuse gas fills the space between galaxies in a cluster. Its free electrons scatter passing CMB photons, which on average gain energy through inverse Compton scattering. The resulting small spectral distortion in the cluster direction is the thermal Sunyaev–Zel’dovich (SZ) effect.'),
        p('電子の熱運動を使うのが熱的SZ。銀河団全体の視線方向の運動による運動学的SZは、最後の発展欄で区別する。この章では銀河団のガスと観測のつながりに集中し、散乱の衝突積分そのものは導かない。', 'Thermal SZ is driven by random electron motion. Kinetic SZ, due to the cluster’s bulk line-of-sight motion, is introduced separately in the final extension. This chapter focuses on the connection between cluster gas and observables, taking the scattering collision operator as a physical input.')),
      s(2, '一回の増幅と、散乱される割合', 'Gain per scattering and scattering probability',
        p('光子のエネルギーをε、電子温度をT_eとする。電子は非相対論的、光子は電子の静止系で十分低エネルギーというトムソン極限を使う。等方的な光子と電子について、速度の二乗まで平均したエネルギー増加率は(4/3)⟨v²/c²⟩となる。', 'Let ε be photon energy and T_e electron temperature. Use nonrelativistic electrons and the Thomson limit: photon energy in the electron rest frame is much smaller than m_ec². For isotropic photons and electrons, averaging to second order in electron speed gives fractional energy gain (4/3)⟨v²/c²⟩.'),
        eq(`⟨v²⟩ = ${f('3k<sub>B</sub>T<sub>e</sub>','m<sub>e</sub>')}<br>⟨${f('Δε','ε')}⟩ ≈ ${f('4','3')}${f('⟨v²⟩','c²')} = 4θ<sub>e</sub>,　θ<sub>e</sub> ≡ ${f('k<sub>B</sub>T<sub>e</sub>','m<sub>e</sub>c²')}`),
        note('4/3は散乱角とドップラー変化の平均からの入力である。光子の反跳による−ε/(m_ec²)の項は、CMB光子と銀河団の熱い電子では小さいため省いた。この4θ_eは一回あたりの平均増幅であり、SZスペクトル全体の形ではない。', 'The factor 4/3 comes from averaging scattering geometry and Doppler shifts. The recoil term −ε/(m_ec²) is negligible for CMB photons scattering on hot cluster electrons. The result 4θ_e is a mean gain per scattering, not the complete SZ spectral shape.'),
        p('一様なガスの電子数密度をn_e、視線方向の厚みをLとすると、散乱光学的厚さはτ＝n_eσ_TL。少なくとも一回散乱する確率は1−e^(−τ)で、τ≪1なら約τとなる。', 'For a uniform electron density n_e and line-of-sight depth L, the scattering optical depth is τ = n_eσ_TL. The probability of at least one scattering is 1 − e^(−τ), approximately τ when τ ≪ 1.'),
        eq(`τ = n<sub>e</sub>σ<sub>T</sub>L,　y ≡ τθ<sub>e</sub><br>${f(t('平均の光子エネルギー増加', 'Mean photon energy gain'),t('元のエネルギー', 'Initial energy'))} ≈ 4y`, '最下段は集団全体の平均エネルギーの一次の見積もり。各周波数の明るさの変化率ではない。', 'The final line estimates the ensemble mean energy gain to first order, not the brightness change at every frequency.')),
      s(3, 'yは、視線に沿った電子圧力を足した量', 'y adds electron pressure along the line of sight',
        p('密度や温度が途中で変わる場合には、小さな区間ごとの寄与dy＝θ_e n_eσ_T dlを足す。電子の理想気体圧力P_e＝n_ek_BT_eを使うと、何を測っているかが見える。', 'If density and temperature vary along the path, add contributions dy = θ_e n_eσ_T dl. Introducing ideal-gas electron pressure P_e = n_ek_BT_e makes the observable explicit.'),
        eq(`y = ∫ ${f('k<sub>B</sub>T<sub>e</sub>','m<sub>e</sub>c²')}n<sub>e</sub>σ<sub>T</sub>dl = ${f('σ<sub>T</sub>','m<sub>e</sub>c²')}∫ P<sub>e</sub>dl`),
        p('σ_Tの単位は面積、P_e dlの単位はエネルギー/面積なのでyは無次元。ここでの圧力は電子の圧力であり、イオンも含む全ガス圧力とは区別する。温度が一定ならy/τがθ_eを与えるが、SZだけでτとT_eを別々に測れるわけではない。', 'σ_T is an area and P_e dl has units of energy per area, so y is dimensionless. P_e is electron pressure, distinct from total gas pressure including ions. At constant temperature y/τ gives θ_e, but a thermal SZ signal alone does not separately determine τ and T_e.'),
        eq(`k<sub>B</sub>T<sub>e</sub> = 8 keV,　n<sub>e</sub> = 10<sup>−3</sup> cm<sup>−3</sup>,　L = 1 Mpc<br>τ ≈ 2.05×10<sup>−3</sup>,　θ<sub>e</sub> ≈ ${f('8','511')},　y ≈ 3.21×10<sup>−5</sup>`),
        p('温度をkeVで書くのはk_BT_eという熱エネルギーを示す慣習である。8 keVは約9.3×10⁷ K。単位変換では1 cm⁻³＝10⁶ m⁻³、1 Mpc≈3.086×10²² mを使う。', 'A temperature quoted in keV denotes the thermal energy k_BT_e. Eight keV corresponds to about 9.3×10⁷ K. Use 1 cm⁻³ = 10⁶ m⁻³ and 1 Mpc ≈ 3.086×10²² m.')),
      s(4, 'プランク分布の変形を計算する', 'Calculate a distortion of the Planck spectrum',
        p('CMBの温度をT₀、周波数をνとし、x＝hν/(k_BT₀)と置く。入門編のプランク分布を、光子の占有数N₀と強度の尺度I₀で書き直す。ここでN₀は電子数密度n_eとは別の量である。', 'Write CMB temperature as T₀ and frequency as ν, and define x = hν/(k_BT₀). Express the Planck spectrum using photon occupation N₀ and intensity scale I₀. N₀ is distinct from electron number density n_e.'),
        eq(`N₀(x) = ${f('1','e<sup>x</sup>−1')},　B<sub>ν</sub> = I₀x³N₀(x)<br>I₀ = ${f('2(k<sub>B</sub>T₀)³','h²c²')}`),
        p('熱い非相対論的電子、τ≪1、y≪1の極限で、Kompaneetsの散乱方程式から得られる一次の変化を出発点として使う。小さいエネルギー変化を繰り返す散乱を、周波数空間の拡散として表した式である。', 'For hot nonrelativistic electrons, τ ≪ 1, and y ≪ 1, take the following first-order consequence of the Kompaneets scattering equation as input. It represents repeated small energy changes as diffusion in frequency space.'),
        eq(`ΔN ≈ ${f('y','x²')}${f('d','dx')}(x⁴${f('dN₀','dx')})`),
        p('dN₀/dx＝−eˣ/(eˣ−1)²を代入する。積の微分でx⁴の項と指数関数の項を分け、ΔI_ν＝I₀x³ΔNへ戻して整理すると、符号を決める括弧が現れる。', 'Insert dN₀/dx = −eˣ/(eˣ−1)². Apply the product rule to x⁴ and the exponential term, then use ΔI_ν = I₀x³ΔN. Collecting terms exposes the bracket that controls the sign.'),
        eq(`ΔI<sub>ν</sub> = I₀y ${f('x⁴e<sup>x</sup>','(e<sup>x</sup>−1)²')} f(x)<br>f(x) ≡ x${f('e<sup>x</sup>+1','e<sup>x</sup>−1')}−4`),
        note('この式は、完全な相対論的散乱を解いたものではない。図には小さな差ΔI_νを表示する。小さいyの式で巨大な歪みを作り、変形後のCMB全体を誇張した曲線として描くことは避ける。', 'This is a leading nonrelativistic result, not a full relativistic scattering solution. The panel displays the small difference ΔI_ν. A small-y expansion should not be used to manufacture an exaggerated, highly distorted full CMB spectrum.')),
      s(5, '低周波で暗くなる理由と、約217 GHzの零点', 'The low-frequency deficit and the approximately 217 GHz null',
        p('x≪1ならeˣ≈1+xなので、x(eˣ+1)/(eˣ−1)→2。よってf(x)→−2となり、低周波側は暗くなる。光子がエネルギーを失ったのではなく、より高い周波数へ再分配されたためである。', 'For x ≪ 1, eˣ ≈ 1+x and x(eˣ+1)/(eˣ−1) tends to two. Thus f(x) tends to −2: a low-frequency deficit. Photons have gained energy and been redistributed toward higher frequencies.'),
        p('周波数ごとの強度差を、黒体の温度変化なら何Kに相当するかで表すことも多い。ΔI_ν＝(∂B_ν/∂T)ΔTの一次換算で、プランク分布を微分すると、', 'Brightness differences are often expressed as the temperature change that would produce them in a blackbody. Linearize ΔI_ν = (∂B_ν/∂T)ΔT and differentiate the Planck function:'),
        eq(`${f('∂B<sub>ν</sub>','∂T')} = ${f('I₀','T₀')}${f('x⁴e<sup>x</sup>','(e<sup>x</sup>−1)²')}<br>${f('ΔT<sub>th</sub>','T₀')} = yf(x)　→　−2y　(x ≪ 1)`),
        p('これは周波数ごとの「CMB熱力学温度への換算」である。CMB全体が一つの別の温度の黒体に変わるわけではない。f(x)＝0の数値解はx≈3.830で、T₀＝2.7255 Kならν≈217.5 GHz。その前後で熱的信号の符号が変わる。', 'This is a frequency-dependent conversion to CMB thermodynamic temperature, not a claim that the distorted spectrum is a blackbody at a different single temperature. Solving f(x) = 0 gives x ≈ 3.830, or ν ≈ 217.5 GHz at T₀ = 2.7255 K. The thermal signal changes sign across this null.'),
        '<div data-lab="sunyaev-zeldovich"></div>',
        note('パネルは非相対論的・一次の式を使い、電子温度を変えても熱的信号の零点は動かない。実際には相対論的補正で形や零点が変わる。温度が高い銀河団の精密な測定には、このパネルの近似をそのまま使わない。', 'The panel uses the leading nonrelativistic formula, so changing electron temperature does not move its thermal null. Relativistic corrections change the spectral shape and null in reality. Precision analysis of hot clusters requires more than this approximation.')),
      s(6, '銀河団について、何が分かるか', 'What does this tell us about a cluster?',
        p('空の各位置でyを測れば、電子の圧力を視線に沿って足した地図になる。温度や密度の別の観測と組み合わせ、銀河団の熱いガスの構造を調べる。ここで「圧力柱が測れた」ことと「全質量が直接決まった」ことは区別する。', 'Measuring y across the sky gives a map of line-of-sight electron pressure. Combine it with other temperature and density measurements to study hot intracluster gas. A pressure-column measurement is not by itself a direct measurement of total cluster mass.'),
        p('同じyでも、薄く熱いガスと、濃く低温のガスをこの一次の熱的SZだけで区別できない。多周波の観測は特徴的な符号の変化を調べる助けになるが、塵の放射、電波源、CMB本来の揺らぎなども同じ空に重なる。', 'The first-order thermal spectrum cannot distinguish hotter, lower-density gas from cooler, denser gas with the same y. Multiple frequencies help isolate its sign-changing spectrum, while dust emission, radio sources, and primary CMB fluctuations must also be considered.')),
      s(7, '発展：運動学的SZを分ける', 'Extension: distinguish kinetic SZ',
        p('銀河団のガスがCMBに対してまとまって動くと、電子のランダムな熱運動とは別に、ドップラー効果による変化が生まれる。視線速度v_∥を観測者から遠ざかる向きに正とし、光学的に薄く|v_∥|≪cとする。', 'Bulk motion of cluster gas relative to the CMB creates a Doppler signal distinct from random thermal motion. Take v_∥ positive away from the observer, with small optical depth and |v_∥| ≪ c.'),
        eq(`${f('ΔT<sub>kin</sub>','T₀')} ≈ −τ${f('v<sub>∥</sub>','c')}`),
        p('遠ざかる場合は負、近づく場合は正。この次数では熱力学温度への換算値が周波数によらず、熱的SZのような約217 GHzでの符号反転を持たない。ただし強度差ΔI_νは∂B_ν/∂Tを掛けるので周波数に依存する。', 'Receding gas gives a negative signal and approaching gas a positive one. At this order the thermodynamic-temperature shift is independent of frequency and has no thermal-style sign reversal near 217 GHz. The intensity difference still depends on frequency through ∂B_ν/∂T.'),
        p('上のパネルで速度を選ぶと、熱的成分に運動学的成分を重ねた差を表示する。例えばτ≈0.00205、v_∥＝300 km/sならΔT_kin≈−5.60 μK。熱的成分の零点でも運動学的成分や他の放射は残りうるので、「217 GHzなら背景だけ」とは解釈しない。', 'Selecting a velocity in the panel adds kinetic SZ to the thermal intensity difference. For example, τ ≈ 0.00205 and v_∥ = 300 km/s give ΔT_kin ≈ −5.60 μK. Kinetic SZ and other emission can remain at the thermal null, so 217 GHz does not isolate the unmodified background.'))
    ].join(''),
    synchrotron: () => [
      s(1, '磁場が軌道を曲げ、電子が光る', 'A magnetic field bends the electron trajectory',
        p('熱い物体の黒体放射とは別に、ほぼ光速の電子が磁場で曲げられて放つ光がある。これがシンクロトロン放射で、電波からX線まで現れうる。以下はSI単位を使い、電子の電荷の大きさをe、質量をm_eと書く。', 'Besides thermal blackbody emission, nearly light-speed electrons radiate when bent by magnetic fields. This synchrotron emission can appear from radio to X-rays. Use SI units, with electron charge magnitude e and mass m_e.'),
        eq(`γ = ${f('1','√(1−v²/c²)')},　E = γm<sub>e</sub>c²<br>r<sub>L</sub> = ${f('γm<sub>e</sub>v<sub>⊥</sub>','eB')}`),
        p('γはローレンツ因子であり、前章の気体の比熱比とは別の記号。同じ文字を使う慣習なので注意する。超相対論的ならγ≫1で、Eと運動エネルギーの違いは小さい。ピッチ角ψは速度と磁場のなす角で、v_⊥＝v sinψ。', 'Here γ is the Lorentz factor, not the gas heat-capacity ratio used in the blast-wave chapter. For γ ≫ 1, total and kinetic energies are nearly equal. The pitch angle ψ is between velocity and magnetic field, with v_⊥ = v sinψ.'),
        note('磁場は電子の向きを変えるが、静的な磁場の力は速度に垂直で仕事をしない。放射エネルギーは電子の運動エネルギーから引かれ、電子は冷える。高エネルギーを保つには加速からの補給が必要になる。', 'A static magnetic field changes direction but does no work because its force is perpendicular to velocity. Radiation drains electron kinetic energy; sustaining high energies requires acceleration or replenishment.')),
      s(2, 'なぜ周波数がγ²に比例するのか', 'Why does the frequency scale as γ²?',
        p('非相対論的なサイクロトロン周波数をν_B＝eB/(2πm_e)とする。相対論的な電子の旋回角速度は小さくなるが、放射は進行方向の角度約1/γに集中する。観測者へ向く短い区間だけが見え、さらに到着時刻が圧縮され、短いパルスになる。', 'Define the nonrelativistic gyrofrequency ν_B = eB/(2πm_e). A relativistic electron gyrates more slowly, but its radiation is beamed into an angle of order 1/γ. The observer sees only the short interval when the beam points toward them, further shortened by arrival-time compression.'),
        p('軌道曲率半径をρ_curvとすると、見える間の放出時間は約ρ_curv/(γc)。到着時間はさらに約γ²分の1なので、代表角周波数はγ³c/ρ_curvの程度。ρ_curv≈γm_ec/(eB sinψ)を入れるとγ²B sinψに比例する。正確な規格化を持つ臨界周波数は、放射理論から次を入力する。', 'For trajectory curvature radius ρ_curv, the emission interval is of order ρ_curv/(γc), and arrival-time compression adds another factor of order γ². The characteristic angular frequency is therefore of order γ³c/ρ_curv. Using ρ_curv ≈ γm_ec/(eB sinψ) gives γ²B sinψ. Radiation theory supplies the exact critical-frequency normalization below.'),
        eq(`ν<sub>c</sub> = ${f('3eB','4πm<sub>e</sub>')}γ² sinψ<br>ν<sub>c</sub> ≈ 4.20 Hz × (${f('B','1 μG')})γ² sinψ`),
        note('1 μG＝10⁻¹⁰ T。ν_cは単色の放射線でも、単電子スペクトルの最大そのものでもない。単電子の周波数スペクトルP_νは幅を持ち、最大は約0.29ν_cにある。この章の操作パネルはν_cの尺度を示し、完全な単電子スペクトルは計算しない。', '1 μG = 10⁻¹⁰ T. ν_c is neither a monochromatic line nor the exact maximum of the single-electron P_ν spectrum, which is broad and peaks near 0.29ν_c. The panel shows the ν_c scale rather than computing the complete single-electron spectrum.')),
      s(3, 'トムソン断面積が再び現れる', 'The Thomson cross section returns',
        p('相対論的な荷電粒子の放射パワーを、入門編で学んだσ_Tで書き直すと見通しがよい。磁場のエネルギー密度U_Bを使う。単一のピッチ角ではP＝2σ_TcU_Bγ²(v/c)²sin²ψ。方向が等方的なら⟨sin²ψ⟩＝2/3となる。', 'Expressing relativistic radiative power through the Thomson cross section σ_T connects to the foundation lesson. Use magnetic energy density U_B. For one pitch angle, P = 2σ_TcU_Bγ²(v/c)²sin²ψ; isotropic directions give ⟨sin²ψ⟩ = 2/3.'),
        eq(`U<sub>B</sub> = ${f('B²','2μ₀')},　⟨P⟩ = ${f('4','3')}σ<sub>T</sub>cU<sub>B</sub>γ²　(γ ≫ 1)`),
        p('これは光子とのトムソン散乱を実行しているという意味ではない。古典的な電荷・質量の組合せを同じ断面積で表したものであり、ここでは相対論的放射公式を入力として使っている。μ₀は真空の透磁率である。', 'This notation does not mean the electron is Thomson-scattering photons here. The same classical charge–mass combination is expressed using σ_T; the relativistic radiation formula is a physical input. μ₀ is the vacuum permeability.'),
        eq(`t<sub>syn</sub> ≡ ${f('E','⟨P⟩')} = ${f('3m<sub>e</sub>c','4σ<sub>T</sub>U<sub>B</sub>γ')} ∝ ${f('1','B²γ')}`),
        '<div data-lab="synchrotron"></div>',
        p('同じBなら高エネルギーの電子ほど速く冷える。逆に、同じ観測周波数ならγ∝(ν/B)^(1/2)なので、冷却時間はB^(−3/2)ν^(−1/2)に比例する。', 'At fixed B, higher-energy electrons cool faster. At a fixed observing frequency, γ ∝ (ν/B)^(1/2), so the cooling time scales as B^(−3/2)ν^(−1/2).')),
      s(4, '電子の指数を、光の指数へ変換する', 'Convert the electron slope to the light spectrum',
        p('電子数のエネルギー分布をN(E)dE＝C E^(−s)dEとする。光学的に薄く、磁場が一定で、注目する範囲に冷却折れ曲がりや端の切断がない場合を考える。説明のため、一つの電子の全パワーを代表周波数ν∝BE²へ集める近似を使う。', 'Let the electron number distribution be N(E)dE = C E^(−s)dE. Assume optically thin emission at fixed magnetic field, away from cooling breaks and energy cutoffs. For the derivation, concentrate each electron’s power near a representative frequency ν ∝ BE².'),
        eq(`j<sub>ν</sub>dν ∝ N(E)P(E)dE<br>j<sub>ν</sub> ∝ E<sup>−s</sup> × B²E² × ${f('1','BE')}<br>j<sub>ν</sub> ∝ B<sup>(s+1)/2</sup>ν<sup>−(s−1)/2</sup>`),
        p('dν/dE∝BEを忘れないことが大切。j_νは周波数幅あたりの放射の強さで、べき乗の傾きαをj_ν∝ν^(−α)と定義するとα＝(s−1)/2。前章のs＝2ならα＝1/2となる。完全な単電子放射関数を積分しても、十分広いべき乗の範囲ではこの指数になる。', 'The Jacobian dν/dE ∝ BE is essential. Define the emissivity slope by j_ν ∝ ν^(−α); then α = (s−1)/2. The preceding chapter’s s = 2 gives α = 1/2. Integrating the full single-electron radiation kernel gives the same slope over a sufficiently broad power-law range.'),
        note('αの符号の定義は文献によって異なる。また、光子数の指数Γは別であり、dN_ph/dε∝ε^(−Γ)ならΓ＝α+1。電子のs、放射のα、光子数のΓを区別しよう。', 'Some references define α with the opposite sign. The photon-number index Γ is also different: dN_ph/dε ∝ ε^(−Γ) gives Γ = α + 1. Distinguish electron index s, emissivity index α, and photon-number index Γ.')),
      s(5, '冷却の微分方程式を解く', 'Solve the cooling equation',
        p('磁場一定・超相対論的・等方的なピッチ角分布なら、γの減り方はdγ/dt＝−aγ²。ここでaは正の定数で、この章だけの冷却係数である。変数を分け、初期値γ₀から積分する。', 'At fixed magnetic field with ultrarelativistic, isotropically distributed electrons, dγ/dt = −aγ². Here a is a positive cooling coefficient used only in this chapter. Separate variables and integrate from the initial value γ₀.'),
        eq(`a = ${f('4σ<sub>T</sub>U<sub>B</sub>','3m<sub>e</sub>c')}<br>${f('1','γ(t)')} − ${f('1','γ₀')} = at<br>γ(t) = ${f('γ₀','1+aγ₀t')}`),
        p('一方、Q(E)∝E^(−s)の注入を一定に続ける模型では、冷却が効く高エネルギー側の定常分布をエネルギー空間の数保存から求められる。逃走を無視してdot E＝−bE²なら、', 'For steady injection Q(E) ∝ E^(−s), the cooled high-energy steady distribution follows from number conservation in energy space. Neglect escape and let dot E = −bE²:'),
        eq(`${f('d','dE')}[ĖN(E)] = Q(E),　Ė ≡ ${f('dE','dt')} = −bE²<br>N(E) = ${f('1','bE²')}∫<sub>E</sub><sup>∞</sup>Q(E′)dE′ ∝ E<sup>−(s+1)</sup>　(s > 1)`),
        p('電子分布の指数が1大きくなるので、光のαは1/2大きくなる。この冷却折れ曲がりは、一定磁場・継続注入・放射損失支配などの条件つき。瞬間的に注入した集団や、逃走が重要な系に同じ形を押しつけない。', 'The electron index steepens by one, so α steepens by one-half. This cooling break assumes constant field, continuous injection, and radiative-loss dominance. An impulsive population or significant escape need not have the same spectrum.')),
      s(6, '観測へ戻るときの条件', 'Return to observations with the assumptions intact',
        p('衝撃波で電子を加速し、磁場中で放射させると、ガスの温度だけでは説明できない連続スペクトルが生まれる。周波数が高い光ほど高エネルギー電子を調べられるが、その電子は冷えるのも速い。', 'Shock acceleration followed by radiation in a magnetic field produces a continuum that gas temperature alone cannot describe. Higher frequencies probe more energetic electrons, which also cool faster.'),
        note('低周波では自己吸収が、高周波では電子の最大エネルギーや冷却が重要になりうる。逆Compton損失・断熱膨張による損失もあり、冷却時間だけで年齢が一意に測れるわけではない。非常に強い磁場や極端な電子エネルギーで量子効果が重要になる領域は、ここで使う古典放射式の範囲外である。', 'Self-absorption can alter low frequencies, while maximum electron energy and cooling affect high frequencies. Inverse-Compton and adiabatic losses also matter, so a cooling time is not a unique age measurement. The classical formulas here exclude regimes where quantum effects become important.'))
    ].join('')
  };
  window.AstroAdvanced = { chapters, sources, renderBody(id, locale) { language = locale; return bodies[id](); } };
})();
